const SCENE_JSONS: &[(&str, &str)] = &[
// (id, scene-json) — the retired declarative cards.
    ("speedtest", SPEEDTEST_SCENE_JSON),
    ("system", SYSTEM_SCENE_JSON),
    ("toggles", TOGGLES_SCENE_JSON),
    ("wallpaper", WALLPAPER_SCENE_JSON),
    ("weather", WEATHER_SCENE_JSON),
    ("wifi", WIFI_SCENE_JSON),
    ("workspaces", WORKSPACES_SCENE_JSON),
    ("worldclock", WORLDCLOCK_SCENE_JSON),
    // stage-5 batch: the interactive declarative cards (scene + host values)
    ("sliders", SLIDERS_SCENE_JSON),
    ("mirror", MIRROR_SCENE_JSON),
    ("compositor", COMPOSITOR_SCENE_JSON),
];

/// The declarative scene for `id`, parsed once. `None` = still on the
/// Lua path (either not declaratively-shaped or not ported yet).
pub(crate) fn declared(id: &str) -> Option<&'static CardScene> {
    static CACHE: OnceLock<Vec<(&'static str, CardScene)>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| {
        SCENE_JSONS
            .iter()
            .map(|(id, js)| {
                (
                    *id,
                    serde_json::from_str::<CardScene>(js)
                        .unwrap_or_else(|e| panic!("scene {id}: {e}")),
                )
            })
            .collect()
    });
    cache.iter().find(|(key, _)| *key == id).map(|(_, sc)| sc)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every registry const parses into a `CardScene` (serde rules the
    /// declarative engine too), so a malformed const fails at test time
    /// instead of on the user's first open card.
    #[test]
    fn every_declared_scene_const_parses() {
        for (id, js) in SCENE_JSONS {
            serde_json::from_str::<CardScene>(js)
                .unwrap_or_else(|e| panic!("{id}: {e}"));
        }
    }
}
